      const isWorkOsAuth = isLikelyWorkOsAuthConfiguration({
        authorizeUrl: resolveOAuthAuthorizeUrl(),
        tokenUrl: tokenUrlRaw,
        clientId,
        issuer: readEnv("ARX_AUTH_JWT_ISSUER"),
        jwksUrl: readEnv("ARX_AUTH_JWT_JWKS_URL"),
      });
